-- Katalog Story Quiz SD–SMA. Idempotent untuk passage dan soal bawaan ini.
UPDATE learn_story_passages SET subject_id=2,grade_level_id=3 WHERE code='semut_belalang';
ON DUPLICATE KEY UPDATE title=VALUES(title),body=VALUES(body),summary=VALUES(summary),subject_id=VALUES(subject_id),grade_level_id=VALUES(grade_level_id),icon=VALUES(icon),color=VALUES(color),estimated_minutes=VALUES(estimated_minutes),is_active=1;

DROP TEMPORARY TABLE IF EXISTS tmp_story_q;
CREATE TEMPORARY TABLE tmp_story_q(code VARCHAR(60),question VARCHAR(500),a VARCHAR(300),b VARCHAR(300),c VARCHAR(300),d VARCHAR(300),correct_option TINYINT,explanation VARCHAR(500),sort_order INT) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DELETE q FROM learn_story_questions q JOIN learn_story_passages p ON p.id=q.passage_id JOIN (SELECT DISTINCT code FROM tmp_story_q) t ON t.code=p.code;
SELECT p.id,t.question,t.a,t.b,t.c,t.d,t.correct_option,t.explanation,t.sort_order,1 FROM tmp_story_q t JOIN learn_story_passages p ON p.code=t.code;
DROP TEMPORARY TABLE tmp_story_q;
